@import "./tokens.css";
@import "./theme.css";

@keyframes bis-caret {
  0%, 45% { opacity: 1; }
  55%, 100% { opacity: 0; }
}
@keyframes bis-sweep {
  from { background-position: 150% 0; }
  to { background-position: -50% 0; }
}
@keyframes bis-spin {
  to { transform: rotate(360deg); }
}
@keyframes bis-breathe {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 1; }
}

/* Live text sweep for in-progress labels (pencil passes across ink). */
.bis-live-text {
  background: linear-gradient(90deg, var(--bis-ink-2) 0%, var(--bis-ink-2) 40%, var(--bis-ink) 50%, var(--bis-ink-2) 60%, var(--bis-ink-2) 100%);
  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: bis-sweep 1.8s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .bis-live-text {
    animation: none;
    color: var(--bis-ink-2);
    background: none;
  }
}

/* Tailwind v4 mapping of Biscotti UI tokens.
 * Usage in a host app:   @import "tailwindcss";
 *                        @import "@biscotti/ui/styles.css";
 *                        @source "../node_modules/@biscotti/ui/src";  (or your copied path)
 */
@theme inline {
  --color-paper: var(--bis-paper);
  --color-surface: var(--bis-surface);
  --color-raised: var(--bis-raised);
  --color-sunken: var(--bis-sunken);
  --color-well: var(--bis-well);
  --color-ink: var(--bis-ink);
  --color-ink-2: var(--bis-ink-2);
  --color-muted: var(--bis-muted);
  --color-faint: var(--bis-faint);
  --color-on-ink: var(--bis-on-ink);
  --color-hairline: var(--bis-hairline);
  --color-rule: var(--bis-rule);
  --color-edge: var(--bis-edge);
  --color-pencil: var(--bis-pencil);
  --color-pencil-ink: var(--bis-pencil-ink);
  --color-pencil-soft: var(--bis-pencil-soft);
  --color-pencil-line: var(--bis-pencil-line);
  --color-ok: var(--bis-ok);
  --color-ok-soft: var(--bis-ok-soft);
  --color-warn: var(--bis-warn);
  --color-warn-soft: var(--bis-warn-soft);
  --color-err: var(--bis-err);
  --color-err-soft: var(--bis-err-soft);
  --color-thumb: var(--bis-thumb);
  --color-field: var(--bis-field);
  --color-thumb-on: var(--bis-thumb-on);
  --color-track-on: var(--bis-track-on);

  --font-sans: var(--bis-font-sans);
  --font-mono: var(--bis-font-mono);
  --font-serif: var(--bis-font-serif);

  --radius-xs: var(--bis-r-xs);
  --radius-sm: var(--bis-r-sm);
  --radius-md: var(--bis-r-md);
  --radius-lg: var(--bis-r-lg);
  --radius-xl: var(--bis-r-xl);

  --shadow-1: var(--bis-shadow-1);
  --shadow-2: var(--bis-shadow-2);
  --shadow-3: var(--bis-shadow-3);
  --shadow-press: var(--bis-press);

  /* type scale — size / line-height / tracking */
  --text-2xs: 11px;
  --text-2xs--line-height: 14px;
  --text-xs: 12px;
  --text-xs--line-height: 16px;
  --text-sm: 13px;
  --text-sm--line-height: 18px;
  --text-base: 14px;
  --text-base--line-height: 20px;
  --text-md: 16px;
  --text-md--line-height: 24px;
  --text-lg: 20px;
  --text-lg--line-height: 26px;
  --text-xl: 28px;
  --text-xl--line-height: 32px;
  --text-2xl: 40px;
  --text-2xl--line-height: 42px;
  --text-3xl: 64px;
  --text-3xl--line-height: 62px;

  --ease-out: var(--bis-ease-out);
  --ease-surface: var(--bis-ease-surface);
}

@utility focus-ring {
  outline: none;
  &:focus-visible {
    box-shadow: var(--bis-focus);
  }
}

@utility tabular {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "zero" 0;
}

@utility hairline-b {
  box-shadow: inset 0 -1px 0 var(--bis-hairline);
}

/* ──────────────────────────────────────────────────────────────
 * Biscotti UI — foundation tokens
 * Plain CSS custom properties. Hosts can remap any --bis-* var.
 * Light is default; dark applies under [data-theme="dark"] or .dark,
 * or automatically with prefers-color-scheme when [data-theme="system"].
 * ────────────────────────────────────────────────────────────── */

:root,
[data-theme="light"] {
  color-scheme: light;
  /* surfaces */
  --bis-paper: #f4f3ef;
  --bis-surface: #fbfbf9;
  --bis-raised: #ffffff;
  --bis-sunken: #ebeae5;
  --bis-well: #e4e3dd;
  /* ink */
  --bis-ink: #16171a;
  --bis-ink-2: #4b4d54;
  --bis-muted: #626469;
  --bis-faint: #a2a4aa;
  --bis-on-ink: #fbfbf9;
  /* lines */
  --bis-hairline: #e1dfd8;
  --bis-rule: #cfccc4;
  --bis-edge: #8e8c86; /* ≥3:1 boundaries for essential controls */
  /* pencil — provisional, live, focus */
  --bis-pencil: #2d54f0;
  --bis-pencil-ink: #1e3ec4;
  --bis-pencil-soft: rgb(45 84 240 / 0.09);
  --bis-pencil-line: rgb(45 84 240 / 0.38);
  /* status */
  --bis-ok: #1d7650;
  --bis-ok-soft: rgb(29 118 80 / 0.1);
  --bis-warn: #9a5f0c;
  --bis-warn-soft: rgb(196 128 20 / 0.13);
  --bis-err: #c8331f;
  --bis-err-soft: rgb(200 51 31 / 0.09);
  /* depth */
  --bis-shadow-1: 0 1px 0 0 rgb(255 255 255 / 0.7) inset, 0 1px 2px -1px rgb(24 22 18 / 0.08);
  --bis-shadow-2: 0 0 0 1px rgb(24 22 18 / 0.06), 0 2px 4px -2px rgb(24 22 18 / 0.08),
    0 12px 28px -10px rgb(24 22 18 / 0.16);
  --bis-shadow-3: 0 0 0 1px rgb(24 22 18 / 0.07), 0 4px 10px -4px rgb(24 22 18 / 0.1),
    0 24px 56px -16px rgb(24 22 18 / 0.24);
  --bis-press: inset 0 1px 2px rgb(24 22 18 / 0.14);
  --bis-highlight: rgb(255 255 255 / 0.75);
  --bis-scrim: rgb(244 243 239 / 0.72);
  --bis-thumb: #ffffff;
  --bis-field: rgb(22 23 26 / 0.05);
  --bis-thumb-on: #ffffff;
  --bis-track-on: #16171a;
  --bis-thumb-edge: rgb(24 22 18 / 0.14);
}

[data-theme="dark"],
.dark {
  color-scheme: dark;
  --bis-paper: #111113;
  --bis-surface: #17171a;
  --bis-raised: #1e1e22;
  --bis-sunken: #0c0c0e;
  --bis-well: #0a0a0b;
  --bis-ink: #edece8;
  --bis-ink-2: #b1b0ad;
  --bis-muted: #939399;
  --bis-faint: #56575d;
  --bis-on-ink: #111113;
  --bis-hairline: #26262b;
  --bis-rule: #323238;
  --bis-edge: #6b6b73;
  --bis-pencil: #7e9bff;
  --bis-pencil-ink: #a5b8ff;
  --bis-pencil-soft: rgb(126 155 255 / 0.12);
  --bis-pencil-line: rgb(126 155 255 / 0.42);
  --bis-ok: #4cc08a;
  --bis-ok-soft: rgb(76 192 138 / 0.12);
  --bis-warn: #e3a648;
  --bis-warn-soft: rgb(227 166 72 / 0.13);
  --bis-err: #ff6f5c;
  --bis-err-soft: rgb(255 111 92 / 0.12);
  --bis-shadow-1: 0 1px 0 0 rgb(255 255 255 / 0.04) inset, 0 1px 2px -1px rgb(0 0 0 / 0.5);
  --bis-shadow-2: 0 0 0 1px rgb(255 255 255 / 0.06), 0 1px 0 0 rgb(255 255 255 / 0.04) inset,
    0 12px 28px -10px rgb(0 0 0 / 0.6);
  --bis-shadow-3: 0 0 0 1px rgb(255 255 255 / 0.07), 0 1px 0 0 rgb(255 255 255 / 0.05) inset,
    0 24px 56px -16px rgb(0 0 0 / 0.7);
  --bis-press: inset 0 1px 2px rgb(0 0 0 / 0.5);
  --bis-highlight: rgb(255 255 255 / 0.06);
  --bis-scrim: rgb(17 17 19 / 0.72);
  --bis-thumb: #63636b;
  --bis-field: rgb(237 236 232 / 0.06);
  --bis-thumb-on: #f3f2ee;
  --bis-track-on: #8a8986;
  --bis-thumb-edge: rgb(0 0 0 / 0.5);
}

@media (prefers-color-scheme: dark) {
  [data-theme="system"] {
    color-scheme: dark;
    --bis-paper: #111113;
    --bis-surface: #17171a;
    --bis-raised: #1e1e22;
    --bis-sunken: #0c0c0e;
    --bis-well: #0a0a0b;
    --bis-ink: #edece8;
    --bis-ink-2: #b1b0ad;
    --bis-muted: #939399;
    --bis-faint: #56575d;
    --bis-on-ink: #111113;
    --bis-hairline: #26262b;
    --bis-rule: #323238;
    --bis-edge: #6b6b73;
    --bis-pencil: #7e9bff;
    --bis-pencil-ink: #a5b8ff;
    --bis-pencil-soft: rgb(126 155 255 / 0.12);
    --bis-pencil-line: rgb(126 155 255 / 0.42);
    --bis-ok: #4cc08a;
    --bis-ok-soft: rgb(76 192 138 / 0.12);
    --bis-warn: #e3a648;
    --bis-warn-soft: rgb(227 166 72 / 0.13);
    --bis-err: #ff6f5c;
    --bis-err-soft: rgb(255 111 92 / 0.12);
  }
}

:root {
  /* type */
  --bis-font-sans: "Geist", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --bis-font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --bis-font-serif: "Newsreader", ui-serif, Georgia, serif;
  /* radius */
  --bis-r-xs: 2px;
  --bis-r-sm: 4px;
  --bis-r-md: 6px;
  --bis-r-lg: 10px;
  --bis-r-xl: 14px;
  /* motion (CSS fallbacks; springs live in motion/tokens.ts) */
  --bis-ease-out: cubic-bezier(0.2, 0.8, 0.2, 1);
  --bis-ease-surface: cubic-bezier(0.16, 1, 0.3, 1);
  --bis-ease-in: cubic-bezier(0.5, 0, 0.75, 0);
  --bis-dur-micro: 90ms;
  --bis-dur-fade: 120ms;
  --bis-dur-surface-in: 200ms;
  --bis-dur-surface-out: 140ms;
  --bis-focus: 0 0 0 2px var(--bis-paper), 0 0 0 4px var(--bis-pencil);
}

"use client";
import { useReducedMotion, type Transition } from "motion/react";

/**
 * Motion tokens — chosen per interaction class, not one global duration.
 * Springs are expressed for `motion` (stiffness/damping/mass).
 */
export const spring = {
  /** Thumbs, small indicators. ζ≈0.85, no visible overshoot. */
  control: { type: "spring", stiffness: 700, damping: 45, mass: 1 },
  /** Mechanical latch — the only token allowed to overshoot (~3–4%). */
  latch: { type: "spring", stiffness: 900, damping: 42, mass: 1 },
  /** Height/collapse/reorder. Near-critical. */
  layout: { type: "spring", stiffness: 380, damping: 38, mass: 1 },
  /** Travelling selection indicators. */
  glide: { type: "spring", stiffness: 520, damping: 44, mass: 1 },
  /** Soft settle for large surfaces entering. */
  surface: { type: "spring", stiffness: 420, damping: 36, mass: 0.9 },
} as const satisfies Record<string, Transition>;

export const ease = {
  out: [0.2, 0.8, 0.2, 1],
  surface: [0.16, 1, 0.3, 1],
  in: [0.5, 0, 0.75, 0],
  inOut: [0.65, 0, 0.35, 1],
} as const;

export const duration = {
  micro: 0.09,
  fade: 0.12,
  surfaceIn: 0.2,
  surfaceOut: 0.14,
  drain: 0.24,
} as const;

export const tween = {
  fade: { duration: duration.fade, ease: ease.out },
  micro: { duration: duration.micro, ease: ease.out },
  surfaceIn: { duration: duration.surfaceIn, ease: ease.surface },
  surfaceOut: { duration: duration.surfaceOut, ease: ease.in },
  drain: { duration: duration.drain, ease: ease.out },
} as const satisfies Record<string, Transition>;

/** Reduced-motion substitute: a short opacity cue, no travel. */
export const reduced: Transition = { duration: 0.12, ease: "linear" };
export const instant: Transition = { duration: 0 };

/**
 * Returns a transition picker that swaps any spring/tween for its
 * reduced-motion equivalent. Travel → instant; opacity → 120ms fade.
 */
export function useMotionTokens() {
  const prefersReduced = useReducedMotion() ?? false;
  return {
    reduced: prefersReduced,
    /** For transforms (x/y/scale/width): instant under reduced motion. */
    move: (t: Transition): Transition => (prefersReduced ? instant : t),
    /** For opacity/colour: keep a short cue under reduced motion. */
    fade: (t: Transition = tween.fade): Transition => (prefersReduced ? reduced : t),
  };
}

/** Surface enter/exit variants (popovers, palettes, toolbars). */
export const surfaceVariants = (from: "top" | "bottom" = "bottom", reducedMotion = false) => {
  const dy = reducedMotion ? 0 : from === "bottom" ? 4 : -4;
  return {
    initial: { opacity: 0, y: dy, scale: reducedMotion ? 1 : 0.985 },
    animate: { opacity: 1, y: 0, scale: 1, transition: reducedMotion ? reduced : tween.surfaceIn },
    exit: { opacity: 0, y: dy / 2, scale: reducedMotion ? 1 : 0.99, transition: reducedMotion ? reduced : tween.surfaceOut },
  };
};

/**
 * Biscotti UI sound engine — every voice is synthesised with the Web Audio API.
 *
 *   voice envelopes → master gain (volume) → limiter → destination
 *
 * • Off by default. `enable()` must be called from a user gesture; it creates
 *   and resumes the AudioContext (browser autoplay policy).
 * • A global voice cap and per-voice rate limits prevent clutter/clipping.
 * • All pitched voices use A‑pentatonic so overlaps stay consonant.
 */

export type SoundName =
  | "tick"
  | "tap"
  | "latch"
  | "unlatch"
  | "select"
  | "confirm"
  | "complete"
  | "attention"
  | "error"
  | "dismiss"
  | "notify"
  | "open"
  | "close";

export interface PlayOptions {
  /** 0–1, scales loudness and filter brightness. Default 0.7. */
  velocity?: number;
  /** Pitch multiplier. Default 1. */
  pitch?: number;
  /** Stereo position −1…1. Default 0. */
  pan?: number;
}

export interface SoundPrefs {
  enabled: boolean;
  volume: number; // 0–1
  /** User chose "never play sounds" — enable() becomes a no-op until cleared. */
  disabledPermanently: boolean;
}

const STORAGE_KEY = "biscotti.sound.v1";
const DEFAULT_PREFS: SoundPrefs = { enabled: false, volume: 0.6, disabledPermanently: false };

// A‑pentatonic reference pitches
const N = { E4: 329.63, B3: 246.94, A4: 440, E5: 659.25, A5: 880, Cs6: 1108.73, E6: 1318.51, A6: 1760 };

const MIN_INTERVAL: Partial<Record<SoundName, number>> = {
  tick: 22,
  select: 40,
  tap: 45,
  latch: 60,
  unlatch: 60,
  confirm: 120,
  complete: 250,
  attention: 1200,
  error: 300,
  notify: 400,
  dismiss: 60,
  open: 120,
  close: 120,
};
const MAX_VOICES = 8;

type Listener = () => void;

class SoundEngine {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private last = new Map<SoundName, number>();
  private active = 0;
  private listeners = new Set<Listener>();
  private prefs: SoundPrefs = DEFAULT_PREFS;
  private hydrated = false;

  /* ── preferences ─────────────────────────────────────────── */

  private hydrate() {
    if (this.hydrated || typeof window === "undefined") return;
    this.hydrated = true;
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (raw) this.prefs = { ...DEFAULT_PREFS, ...JSON.parse(raw), enabled: false };
      // Never auto-enable on load: audio stays silent until a fresh gesture,
      // but we remember the user's last choice so the toggle can restore it.
      const remembered = raw ? JSON.parse(raw).enabled === true : false;
      this.rememberedOn = remembered && !this.prefs.disabledPermanently;
    } catch {
      /* storage unavailable */
    }
  }
  /** Whether the user had sound on last visit (UI may offer one-click restore). */
  rememberedOn = false;

  getPrefs = (): SoundPrefs => {
    this.hydrate();
    return this.prefs;
  };
  getServerPrefs = (): SoundPrefs => DEFAULT_PREFS;

  subscribe = (fn: Listener) => {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  };

  private setPrefs(patch: Partial<SoundPrefs>) {
    this.hydrate();
    this.prefs = { ...this.prefs, ...patch };
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(this.prefs));
    } catch {
      /* ignore */
    }
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(this.gainFor(this.prefs.volume), this.ctx.currentTime, 0.02);
    }
    this.listeners.forEach((l) => l());
  }

  /** Call from a user gesture (click/keydown). */
  enable() {
    this.hydrate();
    if (this.prefs.disabledPermanently) return;
    this.ensureContext();
    void this.ctx?.resume();
    this.setPrefs({ enabled: true });
  }
  disable() {
    this.setPrefs({ enabled: false });
  }
  toggle() {
    if (this.getPrefs().enabled) this.disable();
    else this.enable();
  }
  setVolume(v: number) {
    this.setPrefs({ volume: Math.min(1, Math.max(0, v)) });
  }
  setDisabledPermanently(on: boolean) {
    this.setPrefs({ disabledPermanently: on, enabled: on ? false : this.prefs.enabled });
  }

  /* ── audio graph ─────────────────────────────────────────── */

  private gainFor(volume: number) {
    // perceptual curve, with headroom: max ≈ −6 dBFS pre-limiter
    return Math.pow(volume, 2) * 0.5;
  }

  private ensureContext() {
    if (this.ctx || typeof window === "undefined") return;
    const AC: typeof AudioContext | undefined =
      window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    const ctx = new AC({ latencyHint: "interactive" });
    const master = ctx.createGain();
    master.gain.value = this.gainFor(this.prefs.volume);
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -6;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.002;
    limiter.release.value = 0.12;
    master.connect(limiter).connect(ctx.destination);
    // 0.5 s of white noise, reused by every transient
    const buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.5), ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    this.ctx = ctx;
    this.master = master;
    this.noise = buf;
  }

  /* ── primitives ──────────────────────────────────────────── */

  private out(pan: number): AudioNode {
    const ctx = this.ctx!;
    if (!pan || !ctx.createStereoPanner) return this.master!;
    const p = ctx.createStereoPanner();
    p.pan.value = Math.max(-1, Math.min(1, pan));
    p.connect(this.master!);
    return p;
  }

  private noiseBurst(
    t: number,
    o: { freq: number; q: number; decay: number; gain: number; attack?: number; type?: BiquadFilterType },
    dest: AudioNode,
  ) {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = o.type ?? "bandpass";
    f.frequency.value = o.freq;
    f.Q.value = o.q;
    const g = ctx.createGain();
    const a = o.attack ?? 0.001;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(o.gain, t + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t + a + o.decay);
    src.connect(f).connect(g).connect(dest);
    src.start(t, Math.random() * 0.4);
    src.stop(t + a + o.decay + 0.02);
    return t + a + o.decay;
  }

  private tone(
    t: number,
    o: { freq: number; to?: number; type?: OscillatorType; attack?: number; decay: number; gain: number; lowpass?: number },
    dest: AudioNode,
  ) {
    const ctx = this.ctx!;
    const osc = ctx.createOscillator();
    osc.type = o.type ?? "sine";
    osc.frequency.setValueAtTime(o.freq, t);
    if (o.to) osc.frequency.exponentialRampToValueAtTime(o.to, t + o.decay);
    const g = ctx.createGain();
    const a = o.attack ?? 0.004;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(o.gain, t + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t + a + o.decay);
    let node: AudioNode = osc;
    if (o.lowpass) {
      const lp = ctx.createBiquadFilter();
      lp.type = "lowpass";
      lp.frequency.value = o.lowpass;
      osc.connect(lp);
      node = lp;
    }
    node.connect(g).connect(dest);
    osc.start(t);
    osc.stop(t + a + o.decay + 0.03);
    return t + a + o.decay;
  }

  /* ── voices ──────────────────────────────────────────────── */

  play(name: SoundName, opts: PlayOptions = {}) {
    const prefs = this.getPrefs();
    if (!prefs.enabled || prefs.disabledPermanently || prefs.volume <= 0) return;
    this.ensureContext();
    const ctx = this.ctx;
    if (!ctx || !this.master) return;
    if (ctx.state === "suspended") void ctx.resume();

    const now = performance.now();
    const min = MIN_INTERVAL[name] ?? 50;
    if (now - (this.last.get(name) ?? -Infinity) < min) return;
    if (this.active >= MAX_VOICES) return;
    this.last.set(name, now);

    const v = Math.min(1, Math.max(0.05, opts.velocity ?? 0.7));
    const p = opts.pitch ?? 1;
    const dest = this.out(opts.pan ?? 0);
    const t = ctx.currentTime + 0.003;
    const bright = 0.7 + v * 0.6; // velocity → filter brightness (±30 %)
    let end = t;

    switch (name) {
      case "tick":
        end = this.noiseBurst(t, { freq: 3200 * p * bright, q: 8, decay: 0.018, gain: 0.55 * v }, dest);
        break;
      case "tap":
        this.noiseBurst(t, { freq: 2100 * p * bright, q: 2.2, decay: 0.012, gain: 0.32 * v }, dest);
        end = this.tone(t, { freq: 190 * p, to: 110 * p, decay: 0.045, gain: 0.4 * v, attack: 0.002 }, dest);
        break;
      case "latch":
        this.noiseBurst(t, { freq: 1800 * p, q: 5, decay: 0.012, gain: 0.3 * v }, dest);
        this.noiseBurst(t + 0.026, { freq: 3400 * p * bright, q: 7, decay: 0.016, gain: 0.55 * v }, dest);
        end = this.tone(t + 0.026, { freq: N.E6 * p, decay: 0.06, gain: 0.045 * v, attack: 0.002 }, dest);
        break;
      case "unlatch":
        this.noiseBurst(t, { freq: 3000 * p, q: 6, decay: 0.012, gain: 0.3 * v }, dest);
        end = this.noiseBurst(t + 0.026, { freq: 1500 * p * bright, q: 5, decay: 0.02, gain: 0.48 * v }, dest);
        break;
      case "select":
        this.noiseBurst(t, { freq: 4200 * p * bright, q: 10, decay: 0.01, gain: 0.3 * v }, dest);
        end = this.tone(t, { freq: N.E6 * p, decay: 0.06, gain: 0.045 * v, attack: 0.002 }, dest);
        break;
      case "confirm":
        this.tone(t, { freq: N.A5 * p, type: "triangle", decay: 0.14, gain: 0.09 * v, lowpass: 4000 }, dest);
        this.tone(t, { freq: N.A5 * p, decay: 0.16, gain: 0.07 * v }, dest);
        end = this.tone(t + 0.035, { freq: N.E6 * p, decay: 0.18, gain: 0.07 * v }, dest);
        break;
      case "complete":
        this.tone(t, { freq: N.E5 * p, decay: 0.18, gain: 0.06 * v }, dest);
        this.tone(t + 0.06, { freq: N.A5 * p, decay: 0.2, gain: 0.06 * v }, dest);
        end = this.tone(t + 0.12, { freq: N.E6 * p, decay: 0.32, gain: 0.055 * v }, dest);
        break;
      case "attention":
        this.tone(t, { freq: N.E6 * p, decay: 0.16, gain: 0.08 * v }, dest);
        this.tone(t, { freq: N.E6 * 2 * p, decay: 0.05, gain: 0.012 * v }, dest);
        end = this.tone(t + 0.11, { freq: N.A5 * p, decay: 0.26, gain: 0.08 * v }, dest);
        break;
      case "error":
        this.noiseBurst(t, { freq: 900, q: 1.5, decay: 0.03, gain: 0.18 * v, type: "lowpass" }, dest);
        this.tone(t, { freq: N.E4 * p, type: "triangle", decay: 0.1, gain: 0.16 * v, lowpass: 900 }, dest);
        end = this.tone(t + 0.085, { freq: N.B3 * p, type: "triangle", decay: 0.18, gain: 0.16 * v, lowpass: 800 }, dest);
        break;
      case "dismiss":
        this.noiseBurst(t, { freq: 1600 * p, q: 3, decay: 0.02, gain: 0.24 * v }, dest);
        end = this.tone(t, { freq: 520 * p, to: 300 * p, decay: 0.05, gain: 0.05 * v }, dest);
        break;
      case "notify":
        this.tone(t, { freq: N.E6 * p, decay: 0.32, gain: 0.06 * v }, dest);
        end = this.tone(t, { freq: N.E6 * 2 * p, decay: 0.12, gain: 0.012 * v }, dest);
        break;
      case "open":
        end = this.noiseBurst(t, { freq: 5200 * p, q: 1.2, decay: 0.035, gain: 0.1 * v, attack: 0.008 }, dest);
        break;
      case "close":
        end = this.noiseBurst(t, { freq: 3600 * p, q: 1.2, decay: 0.03, gain: 0.08 * v, attack: 0.004 }, dest);
        break;
    }

    this.active++;
    window.setTimeout(() => {
      this.active = Math.max(0, this.active - 1);
    }, Math.max(30, (end - t) * 1000 + 30));
  }
}

